"use client";
import * as React from "react";
import { variants } from "../lib/variants";

const badge = variants({
  base: "pxui-badge",
  variants: {
    tone: {
      neutral: "pxui-badge-neutral",
      accent: "pxui-badge-accent",
      green: "pxui-badge-green",
      amber: "pxui-badge-amber",
      red: "pxui-badge-red",
      blue: "pxui-badge-blue",
      violet: "pxui-badge-violet",
    },
    size: { sm: "pxui-badge-sm", md: "" },
  },
  defaultVariants: { tone: "neutral", size: "md" },
});

export type BadgeTone = "neutral" | "accent" | "green" | "amber" | "red" | "blue" | "violet";

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  tone?: BadgeTone;
  size?: "sm" | "md";
  /** Statusbolletje links van het label. */
  dot?: boolean;
  icon?: React.ReactNode;
}

/** Badge — compact label voor status, categorie of telling. */
export const Badge = React.forwardRef<HTMLSpanElement, BadgeProps>(function Badge(
  { tone, size, dot, icon, className, children, ...rest },
  ref
) {
  return (
    <span ref={ref} className={badge({ tone, size, className })} {...rest}>
      {dot && <span className="pxui-badge-dot" aria-hidden="true" />}
      {icon}
      {children}
    </span>
  );
});

/* ============================ Badge ============================ */
.pxui-badge {
  display: inline-flex; align-items: center; gap: 5px;
  height: 22px; padding: 0 9px; border-radius: var(--r-full);
  font-size: 12px; font-weight: 600; letter-spacing: -0.005em;
  border: 1px solid transparent; white-space: nowrap;
}
.pxui-badge svg { width: 12px; height: 12px; flex: none; }
.pxui-badge-sm { height: 19px; padding: 0 7px; font-size: 11px; }
.pxui-badge-dot { width: 7px; height: 7px; border-radius: var(--r-full); background: currentColor; flex: none; }

.pxui-badge-neutral { background: var(--surface-3); color: var(--text-2); border-color: var(--border); }
.pxui-badge-accent { background: var(--accent-tint); color: var(--accent-active); border-color: var(--accent-border); }
.pxui-badge-green { background: var(--green-tint); color: var(--green); border-color: var(--green-border); }
.pxui-badge-amber { background: var(--amber-tint); color: var(--amber); border-color: var(--amber-border); }
.pxui-badge-red { background: var(--red-tint); color: var(--red); border-color: var(--red-border); }
.pxui-badge-blue { background: var(--blue-tint); color: var(--blue); border-color: var(--blue-border); }
.pxui-badge-violet { background: var(--violet-tint); color: var(--violet); border-color: var(--violet-border); }
